<script setup>import AppLayout from '../../Layouts/AppLayout.vue';import {useForm} from '@inertiajs/vue3';import {ref} from 'vue';defineProps({projects:Object,clients:Array,members:Array});const open=ref(false);const f=useForm({client_id:'',name:'',description:'',status:'planning',priority:'medium',budget:'',due_date:'',members:[]});const save=()=>f.post('/projects',{onSuccess:()=>{open.value=false;f.reset()}});</script><template><AppLayout><template #title>Projects</template><div class="hero"><p>Centralize client delivery and project operations.</p><button v-if="clients.length" class="btn" @click="open=true">＋ Create project</button></div><div class="panel"><div v-for="p in projects.data" :key="p.id" class="row"><i>{{p.name[0]}}</i><span><Link :href="`/projects/${p.id}`"><b>{{p.name}}</b></Link><small>{{p.client?.name}} · {{p.priority}}</small></span><em>{{p.progress}}%</em><mark>{{p.status}}</mark></div></div><div v-if="open" class="modal"><div class="modal-card"><h2>Create project</h2><form @submit.prevent="save"><input v-model="f.name" placeholder="Project name" required><select v-model="f.client_id" required><option value="">Client</option><option v-for="c in clients" :value="c.id">{{c.name}}</option></select><textarea v-model="f.description" placeholder="Description"></textarea><input v-model="f.budget" type="number" placeholder="Budget"><input v-model="f.due_date" type="date"><select v-model="f.priority"><option>low</option><option>medium</option><option>high</option><option>urgent</option></select><select v-model="f.members" multiple><option v-for="m in members" :value="m.id">{{m.name}} · {{m.role}}</option></select><button class="btn">Create</button><button type="button" @click="open=false">Cancel</button></form></div></div></AppLayout></template>
